const TOLERANCE_PCT = 0.02;
const TOLERANCE_FLOOR_IDR = 50000;
const AUTO_APPROVE_MAX = 10000000;
const MANAGER_MAX = 100000000;
const MINUTES_PER_MANUAL_INVOICE = 7;

function toNum(v) {
  if (v === null || v === undefined || v === '') return 0;
  const n = Number(String(v).split(',').join(''));
  return isNaN(n) ? 0 : n;
}
function makeKey(vendor, invoiceNumber) {
  return (String(vendor || '').trim() + '|' + String(invoiceNumber || '').trim()).toUpperCase();
}
function addDays(iso, days) {
  const t = Date.parse(iso);
  if (isNaN(t)) return '';
  return new Date(t + days * 86400000).toISOString().slice(0, 10);
}
function parseTerms(raw) {
  const terms = String(raw || 'NET 30').toUpperCase().trim();
  const netIdx = terms.indexOf('NET');
  const slash = terms.indexOf('/');
  let netDays = 30;
  let discPct = 0;
  let discDays = 0;
  if (netIdx >= 0) {
    const n = parseInt(terms.slice(netIdx + 3).trim(), 10);
    if (!isNaN(n)) netDays = n;
  }
  if (slash > 0 && netIdx > slash) {
    const parts = terms.slice(0, netIdx).trim().split('/');
    const p = parseFloat(parts[0]);
    const d = parseInt(parts[1], 10);
    if (!isNaN(p)) discPct = p / 100;
    if (!isNaN(d)) discDays = d;
  }
  return { netDays: netDays, discPct: discPct, discDays: discDays, label: terms };
}

const poRows = $('Load Purchase Orders').all();
const grnRows = $('Load Goods Receipts').all();
const ledgerRows = $('Load Posted Invoice Ledger').all();

const poByNumber = {};
for (const it of poRows) {
  const r = it.json || {};
  if (!r.po_number) continue;
  poByNumber[String(r.po_number).trim().toUpperCase()] = r;
}

const grnByPo = {};
for (const it of grnRows) {
  const r = it.json || {};
  if (!r.po_number) continue;
  const k = String(r.po_number).trim().toUpperCase();
  if (!grnByPo[k]) grnByPo[k] = [];
  grnByPo[k].push(r);
}

// A goods receipt can only be billed once. Quantity already invoiced against a
// PO is tracked from two places: rows the ledger already holds from earlier
// runs, and invoices accepted earlier inside this same batch. An exception
// consumes nothing, because nothing is paid against it.
const consumedPosted = {};
const consumedBatch = {};
function consumedTotal(poKey) {
  return (consumedPosted[poKey] || 0) + (consumedBatch[poKey] || 0);
}

const ledgerByKey = {};
for (const it of ledgerRows) {
  const r = it.json || {};
  if (!r.invoice_key) continue;
  if (String(r.decision || '') === 'exception') continue;
  ledgerByKey[String(r.invoice_key).trim().toUpperCase()] = r;
  const lpo = String(r.po_number || '').trim().toUpperCase();
  if (lpo) consumedPosted[lpo] = (consumedPosted[lpo] || 0) + toNum(r.qty_billed);
}

const seenThisBatch = {};
const out = [];

for (const it of $input.all()) {
  const inv = it.json || {};
  const vendor = String(inv.vendor || '').trim();
  const invoiceNumber = String(inv.invoice_number || '').trim();
  const poNumber = String(inv.po_number || '').trim().toUpperCase();
  const sku = String(inv.sku || '').trim().toUpperCase();
  const qtyBilled = toNum(inv.qty_billed);
  const unitPriceBilled = toNum(inv.unit_price);
  const rawAmount = toNum(inv.amount);
  const amountIsSane = rawAmount > 0 && rawAmount < 1e15;
  const amount = amountIsSane ? rawAmount : 0;
  const currency = String(inv.currency || '').trim().toUpperCase();
  const invoiceDate = String(inv.invoice_date || '').trim();
  const invoiceKey = makeKey(vendor, invoiceNumber);

  const problems = [];
  if (!vendor) problems.push('vendor name is missing');
  if (!invoiceNumber) problems.push('invoice number is missing');
  if (!poNumber) problems.push('PO reference is missing');
  if (!amountIsSane) problems.push(rawAmount > 0 ? 'invoice amount ' + rawAmount + ' is outside the plausible range and was not read' : 'invoice amount must be greater than zero');
  if (currency !== 'IDR') problems.push('currency ' + (currency || '(blank)') + ' is not supported, AP posts IDR only');
  if (!invoiceDate || isNaN(Date.parse(invoiceDate))) problems.push('invoice date is missing or unreadable');
  if (amount > 0 && qtyBilled > 0 && unitPriceBilled > 0) {
    const lineTotal = qtyBilled * unitPriceBilled;
    if (Math.abs(lineTotal - amount) > 1) {
      problems.push('invoice total ' + amount + ' does not equal quantity x unit price (' + lineTotal + ')');
    }
  }

  const po = poByNumber[poNumber] || null;
  const grns = grnByPo[poNumber] || [];
  const qtyReceived = grns.reduce(function (s, g) { return s + toNum(g.qty_received); }, 0);
  const grnNumbers = grns.map(function (g) { return String(g.grn_number || ''); }).join(', ');
  const grnCondition = grns.length ? String(grns[0].condition || '') : '';
  const poUnitPrice = po ? toNum(po.unit_price) : 0;
  const qtyOrdered = po ? toNum(po.qty_ordered) : 0;
  const expectedTotal = po ? qtyBilled * poUnitPrice : 0;
  const varianceValue = po ? amount - expectedTotal : 0;
  const varianceAbs = varianceValue < 0 ? -varianceValue : varianceValue;
  const variancePct = expectedTotal > 0 ? varianceValue / expectedTotal : 0;
  const pctAllowance = expectedTotal * TOLERANCE_PCT;
  const allowance = pctAllowance > TOLERANCE_FLOOR_IDR ? pctAllowance : TOLERANCE_FLOOR_IDR;

  // The receipt is drawn down rather than re-read in full for every invoice.
  const qtyMatchable = qtyOrdered < qtyReceived ? qtyOrdered : qtyReceived;
  const qtyPostedBefore = consumedPosted[poNumber] || 0;
  const qtyBatchBefore = consumedBatch[poNumber] || 0;
  const qtyAlreadyInvoiced = consumedTotal(poNumber);
  const qtyOpen = qtyMatchable - qtyAlreadyInvoiced;

  let decision = '';
  let routeTo = '';
  let exceptionCode = '';
  let reason = '';

  if (problems.length) {
    decision = 'exception';
    routeTo = 'ap_clerk';
    exceptionCode = 'VALIDATION';
    reason = 'Rejected before matching: ' + problems.join('; ') + '.';
  } else if (ledgerByKey[invoiceKey]) {
    decision = 'exception';
    routeTo = 'ap_supervisor';
    exceptionCode = 'DUPLICATE';
    reason = 'Already accepted on ' + String(ledgerByKey[invoiceKey].processed_at || 'an earlier run') + ' as ' + String(ledgerByKey[invoiceKey].decision || 'posted') + '. Paying it again would double-pay the vendor.';
  } else if (seenThisBatch[invoiceKey]) {
    decision = 'exception';
    routeTo = 'ap_supervisor';
    exceptionCode = 'DUPLICATE';
    reason = 'The same vendor and invoice number appears more than once inside this batch.';
  } else if (!po) {
    decision = 'exception';
    routeTo = 'procurement';
    exceptionCode = 'PO_NOT_FOUND';
    reason = 'No purchase order ' + poNumber + ' exists. Either the vendor quoted the wrong PO, or this was bought without one.';
  } else if (!grns.length) {
    decision = 'exception';
    routeTo = 'warehouse';
    exceptionCode = 'NO_RECEIPT';
    reason = 'Nothing has been booked in against ' + poNumber + ' yet. Goods receipt must be posted before this invoice can be paid.';
  } else if (qtyBilled > qtyReceived) {
    decision = 'exception';
    routeTo = 'warehouse';
    exceptionCode = 'QTY_MISMATCH';
    reason = 'Billed ' + qtyBilled + ' but only ' + qtyReceived + ' received on ' + grnNumbers + (grnCondition ? ' (' + grnCondition + ')' : '') + '. Short by ' + (qtyBilled - qtyReceived) + '.';
  } else if (qtyBilled > qtyOrdered) {
    decision = 'exception';
    routeTo = 'procurement';
    exceptionCode = 'OVER_PO';
    reason = 'Billed ' + qtyBilled + ' against a PO for ' + qtyOrdered + '. The PO needs a change order before this can be paid.';
  } else if (sku && po.sku && sku !== String(po.sku).trim().toUpperCase()) {
    decision = 'exception';
    routeTo = 'procurement';
    exceptionCode = 'SKU_MISMATCH';
    reason = 'Invoice bills ' + sku + ' but ' + poNumber + ' is for ' + String(po.sku) + '.';
  } else if (qtyBilled > qtyOpen) {
    // Checked before price. A receipt billed twice is a double payment, which is
    // a worse finding than a price procurement can still renegotiate.
    decision = 'exception';
    routeTo = 'ap_supervisor';
    exceptionCode = 'OVER_CONSUMPTION';
    reason = 'Billed ' + qtyBilled + ' but only ' + (qtyOpen > 0 ? qtyOpen : 0) + ' of ' + poNumber + ' is still open. ' + qtyMatchable + ' matchable (ordered ' + qtyOrdered + ', received ' + qtyReceived + ' on ' + grnNumbers + ') less ' + qtyAlreadyInvoiced + ' already invoiced (' + qtyPostedBefore + ' on the posted ledger, ' + qtyBatchBefore + ' earlier in this batch). Paying this would bill the same goods receipt twice.';
  } else if (varianceAbs > allowance) {
    decision = 'exception';
    routeTo = 'procurement';
    exceptionCode = 'PRICE_VARIANCE';
    reason = 'Billed ' + amount + ' against an expected ' + expectedTotal + ' at the PO price of ' + poUnitPrice + ' per unit. Over tolerance by ' + Math.round(varianceAbs - allowance) + '.';
  } else if (amount <= AUTO_APPROVE_MAX) {
    decision = 'auto_approve';
    routeTo = 'accounting_auto';
    reason = 'Three-way match clean and under the touchless ceiling of ' + AUTO_APPROVE_MAX + '. Posted without human review.';
  } else if (amount <= MANAGER_MAX) {
    decision = 'needs_approval';
    routeTo = 'manager';
    reason = 'Three-way match clean. Above the touchless ceiling, so a manager signs off before posting.';
  } else {
    decision = 'needs_approval';
    routeTo = 'director';
    reason = 'Three-way match clean but above ' + MANAGER_MAX + '. Director approval required.';
  }

  /* Satu faktur bisa melanggar lebih dari satu aturan. exception_code tetap
     yang pertama menurut prioritas, karena itu yang menentukan pemiliknya,
     tapi menyembunyikan sisanya berarti procurement tidak pernah tahu bahwa
     harganya juga salah. Semua yang gagal dicatat, bukan cuma yang pertama. */
  const allCodes = [];
  if (problems.length) allCodes.push("VALIDATION");
  if (ledgerByKey[invoiceKey] || seenThisBatch[invoiceKey]) allCodes.push("DUPLICATE");
  if (!po) allCodes.push("PO_NOT_FOUND");
  if (po && !grns.length) allCodes.push("NO_RECEIPT");
  if (po && grns.length && qtyBilled > qtyReceived) allCodes.push("QTY_MISMATCH");
  if (po && qtyBilled > qtyOrdered) allCodes.push("OVER_PO");
  if (po && sku && po.sku && sku !== String(po.sku).trim().toUpperCase()) allCodes.push("SKU_MISMATCH");
  /* Hanya kalau memang ada yang sudah ditagihkan sebelumnya. Bila belum,
     OVER_CONSUMPTION persis sama artinya dengan QTY_MISMATCH dan menyebut
     keduanya cuma bising. */
  if (po && grns.length && qtyAlreadyInvoiced > 0 && qtyBilled > qtyOpen) allCodes.push("OVER_CONSUMPTION");
  if (po && varianceAbs > allowance) allCodes.push("PRICE_VARIANCE");
  /* VALIDATION berarti faktur ditolak SEBELUM dicocokkan, jadi angka kuantitas
     dan nilainya memang sampah - melaporkan kegagalan pencocokan di atasnya
     hanya menyesatkan pemiliknya. */
  const secondaryCodes = exceptionCode === "VALIDATION" ? []
    : allCodes.filter(function (c) { return c !== exceptionCode; });
  const secondaryNote = secondaryCodes.length
    ? "Also failing: " + secondaryCodes.join(", ") + ". Routed on " + exceptionCode + ", but these need an owner too."
    : "";
  seenThisBatch[invoiceKey] = true;

  // Only an invoice that is actually going to be paid draws the receipt down.
  if (decision !== 'exception' && poNumber) {
    consumedBatch[poNumber] = (consumedBatch[poNumber] || 0) + qtyBilled;
  }

  const ledgerKey = decision === 'exception' ? invoiceKey + ' #' + exceptionCode : invoiceKey;

  const terms = parseTerms(inv.payment_terms);
  const dueDate = invoiceDate && !isNaN(Date.parse(invoiceDate)) ? addDays(invoiceDate, terms.netDays) : '';
  const discountDate = terms.discPct > 0 && dueDate ? addDays(invoiceDate, terms.discDays) : '';
  const discountAmount = terms.discPct > 0 && decision !== 'exception' ? Math.round(amount * terms.discPct) : 0;
  const payable = decision === 'exception' ? 0 : amount - discountAmount;

  // A needs_approval invoice still costs a human their attention, so it is not
  // touchless and no clerk minutes are claimed for it.
  const humanTouches = decision === 'auto_approve' ? 0 : 1;

  out.push({
    json: {
      invoice_key: invoiceKey,
      ledger_key: ledgerKey,
      vendor: vendor,
      invoice_number: invoiceNumber,
      invoice_date: invoiceDate,
      po_number: poNumber,
      sku: sku,
      qty_billed: qtyBilled,
      unit_price: unitPriceBilled,
      amount: amount,
      currency: currency,
      decision: decision,
      route_to: routeTo,
      exception_code: exceptionCode,
      exception_codes: decision === "exception" ? allCodes : [],
      secondary_exception_codes: decision === "exception" ? secondaryCodes : [],
      secondary_note: decision === "exception" ? secondaryNote : "",
      note: reason,
      po_found: po ? true : false,
      po_vendor: po ? String(po.vendor || '') : '',
      po_qty_ordered: qtyOrdered,
      po_unit_price: poUnitPrice,
      po_buyer: po ? String(po.buyer || '') : '',
      grn_numbers: grnNumbers,
      grn_qty_received: qtyReceived,
      grn_condition: grnCondition,
      qty_matchable: qtyMatchable,
      qty_already_invoiced: qtyAlreadyInvoiced,
      qty_already_invoiced_posted: qtyPostedBefore,
      qty_already_invoiced_this_batch: qtyBatchBefore,
      qty_open: qtyOpen,
      expected_total: expectedTotal,
      variance_value: varianceValue,
      variance_pct: Math.round(variancePct * 10000) / 100,
      tolerance_allowance: Math.round(allowance),
      payment_terms: terms.label,
      due_date: dueDate,
      discount_date: discountDate,
      discount_amount: discountAmount,
      payable_amount: payable,
      validation_problems: problems,
      human_touches: humanTouches,
      minutes_saved: humanTouches === 0 ? MINUTES_PER_MANUAL_INVOICE : 0,
      processed_at: new Date().toISOString(),
      execution_id: String($execution.id || 'manual')
    }
  });
}

return out;

