const rows = $('Three-Way Match and Payment Engine').all().map(function (i) { return i.json; });

// What actually came back from the ledger write, not what was sent to it.
// The write node is wired straight in: a node-level failure now stops the run
// outright instead of ending green, so there is no alert branch to merge. What
// this still has to catch is the quieter fault - the node succeeding while a
// row never lands - so a lost row is counted here rather than assumed away.
//
// A row is only counted as written when the data table handed it back with its
// own row id and updatedAt stamp. Counting anything that is merely not flagged
// would still report 11 of 11 when the whole node falls over and passes its
// input straight through, which is exactly the lie this count exists to stop.
const outcomes = $input.all().map(function (i) { return i.json || {}; });
function confirmedWritten(r) {
  return !!r.invoice_key && !!r.updatedAt && r.id !== undefined && r.id !== null && !r.alert;
}
const written = outcomes.filter(confirmedWritten);
const notWritten = outcomes.filter(function (r) { return !confirmedWritten(r); });
const writeOk = written.length;
const writeFailed = rows.length - writeOk;
const failedKeys = notWritten.map(function (r) {
  return String(r.ledger_key || r.invoice_key || '(unknown invoice)');
});
const neverReturned = writeFailed - notWritten.length;
if (neverReturned > 0) {
  failedKeys.push('(' + neverReturned + ' more the ledger node never reported back at all)');
}

let journalEntries = [];
try {
  journalEntries = $('Draft Journal Entry').all().map(function (i) {
    const r = i.json || {};
    return {
      reference: String(r.posting_reference || ''),
      invoice: String(r.invoice_number || ''),
      vendor: String(r.vendor || ''),
      amount: Number(r.amount) || 0,
      entry: String(r.journal_entry || '')
    };
  });
} catch (e) {
  journalEntries = [];
}

const total = rows.length;
const autoPosted = rows.filter(function (r) { return r.decision === 'auto_approve'; });
const pending = rows.filter(function (r) { return r.decision === 'needs_approval'; });
const held = rows.filter(function (r) { return r.decision === 'exception'; });

function sum(list, field) {
  return list.reduce(function (s, r) { return s + (Number(r[field]) || 0); }, 0);
}

const byCode = {};
for (const r of held) {
  const c = r.exception_code || 'UNKNOWN';
  if (!byCode[c]) byCode[c] = { code: c, count: 0, value: 0, owners: {} };
  byCode[c].count = byCode[c].count + 1;
  byCode[c].value = byCode[c].value + (Number(r.amount) || 0);
  byCode[c].owners[r.route_to || 'unassigned'] = true;
}
const exceptionBreakdown = Object.keys(byCode).map(function (c) {
  return {
    code: c,
    count: byCode[c].count,
    value: byCode[c].value,
    owner: Object.keys(byCode[c].owners).join(', ')
  };
}).sort(function (a, b) { return b.value - a.value; });

const byVendor = {};
for (const r of rows) {
  const v = r.vendor || '(no vendor)';
  if (!byVendor[v]) byVendor[v] = { vendor: v, invoices: 0, billed: 0, payable: 0, held: 0 };
  byVendor[v].invoices = byVendor[v].invoices + 1;
  byVendor[v].billed = byVendor[v].billed + (Number(r.amount) || 0);
  byVendor[v].payable = byVendor[v].payable + (Number(r.payable_amount) || 0);
  if (r.decision === 'exception') byVendor[v].held = byVendor[v].held + (Number(r.amount) || 0);
}
const totalBilled = sum(rows, 'amount');
const vendorBreakdown = Object.keys(byVendor).map(function (v) {
  const b = byVendor[v];
  b.share_pct = totalBilled > 0 ? Math.round((b.billed / totalBilled) * 1000) / 10 : 0;
  return b;
}).sort(function (a, b) { return b.billed - a.billed; });

const discounts = rows.filter(function (r) { return (Number(r.discount_amount) || 0) > 0; })
  .map(function (r) {
    return {
      invoice: r.invoice_number,
      vendor: r.vendor,
      save: Number(r.discount_amount) || 0,
      pay_by: r.discount_date,
      terms: r.payment_terms
    };
  }).sort(function (a, b) { return b.save - a.save; });

const schedule = rows.filter(function (r) { return r.decision !== 'exception' && r.due_date; })
  .map(function (r) {
    return {
      pay_on: r.discount_date || r.due_date,
      invoice: r.invoice_number,
      vendor: r.vendor,
      amount: Number(r.payable_amount) || 0,
      approval: r.route_to
    };
  }).sort(function (a, b) { return a.pay_on < b.pay_on ? -1 : 1; });

const touchlessCount = rows.filter(function (r) { return (Number(r.human_touches) || 0) === 0; }).length;
const touchless = total ? Math.round((touchlessCount / total) * 1000) / 10 : 0;
const minutesSaved = sum(rows, 'minutes_saved');
const humanTouches = sum(rows, 'human_touches');

const overConsumption = held.filter(function (r) { return r.exception_code === 'OVER_CONSUMPTION'; });

return [{
  json: {
    run_id: String($execution.id || 'manual'),
    ran_at: new Date().toISOString(),
    invoices_processed: total,
    auto_posted_count: autoPosted.length,
    auto_posted_value: sum(autoPosted, 'amount'),
    awaiting_approval_count: pending.length,
    awaiting_approval_value: sum(pending, 'amount'),
    held_count: held.length,
    held_value: sum(held, 'amount'),
    total_billed: totalBilled,
    total_payable: sum(rows, 'payable_amount'),
    touchless_count: touchlessCount,
    touchless_rate_pct: touchless,
    human_touches_required: humanTouches,
    clerk_minutes_saved: minutesSaved,
    early_payment_savings: sum(rows, 'discount_amount'),
    ledger_writes_attempted: total,
    ledger_writes_ok: writeOk,
    ledger_writes_failed: writeFailed > 0 ? writeFailed : 0,
    ledger_write_failures: failedKeys,
    over_consumption_count: overConsumption.length,
    over_consumption_value: sum(overConsumption, 'amount'),
    journal_entries: journalEntries,
    discount_opportunities: discounts,
    exception_breakdown: exceptionBreakdown,
    vendor_breakdown: vendorBreakdown,
    payment_schedule: schedule,
    exceptions: held.map(function (r) {
      return {
        invoice: r.invoice_number || '(no number)',
        vendor: r.vendor || '(no vendor)',
        po: r.po_number,
        amount: r.amount,
        code: r.exception_code,
        owner: r.route_to,
        why: r.note,
        also: Array.isArray(r.secondary_exception_codes) ? r.secondary_exception_codes : []
      };
    })
  }
}];

